<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;700&amp;family=Georgia:wght@400;700&amp;display=swap');

        body {
            margin: 0;
            padding: 0;
            background: #f8f8f8;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            font-family: 'Georgia', serif;
        }

        .document {
            max-width: 800px;
            margin: 40px auto;
            background: #ffffff;
            box-shadow: 0 0 30px rgba(0, 0, 0, 0.15);
            overflow: hidden;
        }

        .header {
            text-align: center;
            padding: 30px 20px 20px;
            border-bottom: 3px double #000;
        }

        .header h1 {
            font-family: 'Times New Roman', serif;
            font-size: 28px;
            margin: 0 0 8px 0;
            letter-spacing: 4px;
            font-weight: 700;
        }

        .header .subtitle {
            font-family: 'Times New Roman', serif;
            font-size: 16px;
            margin: 0;
            letter-spacing: 2px;
            font-weight: 400;
        }

        .content {
            padding: 40px 30px 50px;
            line-height: 1.65;
        }

        .section {
            margin-bottom: 32px;
        }

        .section-title {
            font-family: 'Times New Roman', serif;
            font-size: 18px;
            font-weight: 700;
            margin-bottom: 12px;
            border-bottom: 1px solid #000;
            padding-bottom: 4px;
        }

        p {
            margin: 0 0 14px 0;
            text-indent: 20px;
        }

        .indent {
            text-indent: 20px;
        }

        .list {
            margin: 16px 0 24px 0;
            padding-left: 30px;
        }

        .list li {
            margin-bottom: 8px;
        }

        .highlight {
            font-weight: 700;
            font-style: italic;
        }

        .footer {
            text-align: center;
            font-size: 12px;
            color: #555;
            padding: 20px;
            border-top: 1px solid #ccc;
        }
    </style>
</head>
<body>
    <div class="document">
        <!-- HEADER -->
        <div class="header">
            <h1>CONFIDENTIAL</h1>
            <div class="subtitle">INTERNAL MEMORANDUM</div>
        </div>

        <!-- CONTENT -->
        <div class="content">

            <!-- DATE -->
            <p><strong>Date:</strong> July 15, 2025</p>

            <!-- TO -->
            <p><strong>To:</strong> All Department Heads</p>

            <!-- SUBJECT -->
            <p><strong>Subject:</strong> Quarterly Performance Review</p>

            <!-- BODY -->
            <p>This memorandum outlines the key objectives for the upcoming fiscal quarter.</p>

            <div class="section">
                <div class="section-title">Key Initiatives</div>
                <ul>
                    <li>Enhance customer satisfaction by 15%</li>
                    <li>Launch new product line in Q3</li>
                    <li>Implement cost-saving measures</li>
                </ul>
            </div>

            <p class="indent">All staff are expected to contribute to these goals.</p>

            <div class="section">
                <div class="section-title">Action Items</div>
                <ul>
                    <li>Department A: Report by August 1</li>
                    <li>Department B: Present presentation on September 10</li>
                </ul>
            </div>

            <p class="highlight">Failure to meet targets may result in disciplinary action.</p>

        </div>

        <!-- FOOTER -->
        <div class="footer">
            This is a confidential document.<br>
            Page 1 of 2
        </div>
    </div>
</body>
</html>
